-- 初始数据：菜单、角色、部门、参数和一个默认管理员。先执行 0001_create_tables.sql 建表，再执行本文件。
-- 菜单：系统管理、系统日志、用户管理三组，有页面也有按钮。按钮行的 name 就是权限键。
-- 默认管理员：user_id 为 superadmin（代码据此跳过权限检查），登录名 admin，密码 admin123。
--       前端提交的是三次 MD5 后的值，这里存的也是。上线前必须改密码。

-- 菜单
SELECT setval('db_sys_menus_id_seq', (SELECT max(id) FROM db_sys_menus));

-- 角色
SELECT setval('db_sys_role_id_seq', (SELECT max(id) FROM db_sys_role));

-- 部门
SELECT setval('db_sys_dept_id_seq', (SELECT max(id) FROM db_sys_dept));

-- 参数。config_id 的序列从 100000 开始，下面这 20 行的 config_id 是直接给的，序列不用调整。

-- 默认管理员
VALUES ('superadmin', 'admin', '105dad91250a07b716d6a714a3e676b8', '超级管理员', -1, 1, '{r_AdminSuper}', 1, '127.0.0.1');
